{"source": "def poly(x, a, b, c):
    return a * x + b * x * x + c * x * x * x

def contributions(values, a, b, c, g, mode):
    out = []
    total = 0
    prev = 0
    for x in values:
        base = poly(x, a, b, c)
        if mode == 0:
            base = base + g * x * prev
        else:
            base = base + g * x * total
        out.append(base)
        total = total + x
        prev = x
    return out

def passes(contribs, n):
    cur = contribs
    for _ in range(n):
        acc = 0
        nxt = []
        for v in cur:
            acc = acc + v
            nxt.append(acc)
        cur = nxt
    return cur

def evaluate(values, a, b, c, g, mode, n):
    if not values:
        return 0
    return passes(contributions(values, a, b, c, g, mode), n)[-1]

def investigate(context, acquire):
    values = context["values"]
    if not values:
        return 0
    best = None
    best_err = None
    for a in (-2, -1, 0, 1, 2):
        for b in (-2, -1, 0, 1, 2):
            for c in (-2, -1, 0, 1, 2):
                for g in (-2, -1, 1, 2):
                    for mode in (0, 1):
                        for n in (1, 2, 3, 4):
                            err = 0
                            for probe in acquire():
                                pv = probe["values"]
                                if pv:
                                    got = evaluate(pv, a, b, c, g, mode, n)
                                    err = err + abs(got - probe["expected"])
                            if best_err is None or err < best_err:
                                best_err = err
                                best = (a, b, c, g, mode, n)
    a, b, c, g, mode, n = best
    return evaluate(values, a, b, c, g, mode, n)
